#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.13.0  -  Settings, privacy, language, new Details screen
#   * Settings (search, Saved, History, Manage time, Add account, Account privacy, Blocked,
#     Accessibility, Language, App update, About, Privacy policy, Terms, Log out).
#   * Private account + follow requests, block people, age check (13+) at sign-up.
#   * Create > Details: big cover, change cover, audience, share to moments, hide counts.
#   * Clips fit the whole screen, Report with a written problem, Explore shows clips only.
#   * Profile: Settings button, Share profile, smaller numbers, story ring on every avatar.
#   * Languages: English, Hindi, Spanish, French (main screens).
# Run from the project root:   bash update_v1130_settings_privacy_details.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="4f9441e97298bdcc4e0ba8aef1a89a5be98ab720f2aeeec232b2515d3585206f"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/services/call_service.dart ] || { echo "ERROR: v1.11.0 is not installed. Run update_v1110_calls_share_fixes.sh first."; exit 1; }
[ -f lib/widgets/post_details_sheet.dart ] || { echo "ERROR: v1.12.0 is not installed. Run update_v1120_create_carousel_music.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')
echo "    Dart package: $APP_NAME"

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the updated files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

echo "==> Adding shared_preferences to pubspec.yaml..."
python3 - pubspec.yaml <<'PYX'
import re, sys
p = sys.argv[1]
s = open(p).read()
if re.search(r"^[ \t]+shared_preferences:", s, re.M):
    print("    already there")
else:
    m = re.search(r"^dependencies:[ \t]*\r?\n", s, re.M)
    if not m:
        sys.exit("ERROR: no dependencies: section in pubspec.yaml")
    s = s[:m.end()] + "  shared_preferences: ^2.5.3\n" + s[m.end():]
    open(p, "w").write(s)
    print("    added")
PYX

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.13.0 is in place."
echo ""
echo "IMPORTANT (once):"
echo "  1) Firestore rules: Firebase console -> Firestore Database -> Rules, paste the full"
echo "     contents of firebase/firestore.rules and press Publish. Private accounts, blocking,"
echo "     share counts and the new post options need them."
echo "  2) Music (only if you have not yet): Vercel -> signer project -> Settings -> Environment"
echo "     Variables -> EPIDEMIC_API_KEY, then Deployments -> Redeploy."
echo ""
echo "Next:"
echo "  flutter clean && flutter pub get && dart analyze && flutter test"
echo '  git add -A && git commit -m "v1.13.0: settings, privacy, language, new details screen" && git push'
exit 0
